<script setup lang="ts">
import type { AnswerRef, ToolCall } from '../types'
defineProps<{ calls: ToolCall[]; references?: AnswerRef[] }>()
function reveal(id: string) { const element = document.getElementById('tool-' + id); element?.setAttribute('open', ''); element?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
</script>
<template><section class="panel trace" data-testid="tool-trace"><h2>工具调用轨迹 <small>{{ calls.length }} 次</small></h2><div v-if="references?.some(item => item.kind === 'DATA')" class="form-row"><button v-for="item in references.filter(item => item.kind === 'DATA')" :key="item.tool_call_id" @click="reveal(item.tool_call_id)">查看数据依据 · {{ calls.findIndex(call => call.tool_call_id === item.tool_call_id) + 1 }}</button></div><p v-if="!calls.length" class="muted">等待服务器工具记录</p><details v-for="(call, index) in calls" :id="`tool-${call.tool_call_id}`" :key="call.tool_call_id"><summary><span class="trace-index">{{ index + 1 }}</span><code>{{ call.tool_name }}</code><span class="pill" :class="{ offline: call.status === 'failed', online: call.status === 'succeeded' }">{{ { running: '执行中', succeeded: '成功', failed: '失败' }[call.status] || call.status }}</span></summary><p v-if="call.error_code" class="orange">{{ call.error_code }}</p><small>内部调用 {{ call.tool_call_id }} · {{ call.duration_ms?.toFixed(0) ?? '—' }} ms</small><pre>{{ JSON.stringify({ arguments: call.args_json, result: call.result_json }, null, 2) }}</pre></details></section></template>
